L002206	\se{C. Proof of Lemma~5}
L002207	From \eqref{eq-om}, the problem is to find the number of integers
L002208	$y\in(-\pi,\pi]$
L002209	satisfying
L002210	$\sin\paren{\f{2\pi}L(y+\f m2)}\in[x-\d, x+\d]$,
L002211	which is twice the number of such integers
L002212	$y\in(-\f\pi2,\f\pi2]$.
L002213	We assume $x\ge0$ without loss of generality
L002214	because
L002215	$\abs{\om_m(x,\d)}$ does not depend on the signature of $x$.
L002216	When $1-\d<  x\le 1+\d$, we observe that
L002217	$\abs{\om_m(x,\d)}\le\abs{\om_m(1-\d,\d)}$.
L002218	When $0\le x\le 1-\d$, we have
L002219	\begin{align}
L002220	  \abs{\om_m(x,\d)}
L002221	  \le 2\Bigl(
L002222	  \f {L}{2\pi}\paren{\Arcsin(x+\d)-\Arcsin(x-\d)}
L002223	  +1
L002224	  \Bigr)
L002225	\end{align}
L002226	{}(the range of $\Arcsin$ is $[-\pi/2,\pi/2]$).
L002227	Therefore, Lemma~5 is proven
L002228	(also from $2\sqrt2<\pi$) once the following inequality is proven
L002229	for $0 < \delta \leq 1/2$ and $0\le x\le 1-\d$:
L002230	\begin{align}
L002231	  \Arcsin(x+\d)-\Arcsin(x-\d)
L002232	  \le \f{2\sqrt2 \d}{\sqrt{1-x^2}}.
L002233	  \label{eq-arcsin}
L002234	\end{align}
L002235	To prove \eqref{eq-arcsin},
L002236	let $\ep$ be the LHS.
L002237	Since $\ep$ is increasing in $x$ (easily seen by
L002238	differentiation with respect to $x$),
L002239	$\ep\le \ep|_{x=1-\d}=
L002240	\Arcsin(1)-\Arcsin(1-2\d)<\pi/2$.
L002241	Let $\tht:=\Arcsin(x+\d)$.
L002242	It is seen by taking squares of both hand sides
L002243	of \eqref{eq-arcsin}
L002244	that
L002245	\eqref{eq-arcsin} is equivalent to
L002246	  \begin{align}
L002247	    Y(\tht,\ep):=\f{8\paren{\sin\tht-\sin(\tht-\ep)}^2}
L002248	    {4-\paren{\sin\tht+\sin(\tht-\ep)}^2}-\ep{}^2
L002249	    \ge0.
L002250	  \end{align}
L002251	$Y$ is non-increasing in $\tht$ because
L002252	  \begin{align}
L002253	    \pder Y{\tht}
L002254	    =
L002255	    -\frac
L002256	    {128
L002257	    \bigparen{\sin\f{\ep}2}^4
L002258	    \sin (2 \tht-\ep)
L002259	    }
L002260	    {\bigl \{
L002261	    4-\paren{\sin\tht+\sin(\tht-\ep)}^2
L002262	    \bigr \}^2}
L002263	    \le0,
L002264	  \end{align}
L002265	  where $x\ge0$ implies $\sin (2 \tht-\ep )\ge0$.
L002266	  Thus,
L002267	  $Y(\tht,\ep)\ge Y(\pi/2,\ep)
L002268	  =\{8-3 \ep{} ^2-(8
L002269	  +\ep{} ^2) \cos \ep\}
L002270	  /\{3+\cos\ep\}$.
L002271	    Because $\cos\ep\le1-\ep{}^2/2+\ep{}^4/24$,
L002272	    (the numerator of $Y(\pi/2,\ep)$)
L002273	    $
L002274	     \ge \ep{} ^4 (2-\ep ) (2+\ep)/24.
L002275	    $
L002276	    This is nonnegative because $\ep\in(0,\pi/2)$.
L002277	    We have proven \eqref{eq-arcsin},
L002278	    and hence Lemma~5.
L002279	\qed
