L002282	\se{D. Proof of Lemma~6}
L002283	
L002284	
L002285	
L002286	
L002287	For $d=1$, $x=E/\abs{C_m}$ and $\d=1/(\abs{C_m}\ta)$,
L002288	we have
L002289	\begin{align}
L002290	 & \II_m
L002291	  =
L002292	    \f1 {2\d}
L002293	    \int_{-1-\d}^{1+\d}
L002294	    \dd x\;
L002295	  \abs{\om_m(x,\d)}^2
L002296	  \nn
L002297	  &\le
L002298	 \frac{1}{2\d}\int_{-1-\d}^{1+\d}\dd x\;
L002299	    \Bigl (
L002300	    \f{(L\d)^2}{1-\{\abs x\we (1-\d)\}^2}+4\abs{\om_m(x,\d)}
L002301	    \Bigr ) .
L002302	    \label{eq-Im-bd}
L002303	\end{align}
L002304	In the last inequality, we used Lemma~5
L002305	for the integrand
L002306	and the fact that
L002307	\footnote{Proof: the claimed
L002308	inequality is equivalent to $(a-b)(a+b) \leq 2 a c$.
L002309	This
L002310	is trivially true for  $a < b$.
L002311	For $a \geq b$, we have
L002312	$(a-b)(a+b) \leq c(a+b) \leq 2 a c$, because $a-b \leq c$.}
L002313	$a\le b+c$
L002314	for $a,b,c\ge0$
L002315	implies $a^2\le b^2+ 2ac$.
L002316	
L002317	The integral of $\abs{\om_m(x,\d)}$
L002318	equals the number $L$ of total possible states $\b$,
