L002363	\se{E. Proof of Lemma~7}
L002364	
L002365	
L002366	We reduce the case of $d\ge2$ to that of
L002367	$d=1$.
L002368	Fix $\mm$, and let $m$ be the component of $\mm$ with the largest magnitude
L002369	(take one if there are two or more).
L002370	We also decompose $\bb$ accordingly and write $\bb = (\b,\bb')$
L002371	(i.e., if $m$ is the $\m^{\rm th}$ component of $\mm$, $\b$ is the
L002372	 $\m^{\rm th}$
L002373	component of $\bb$).
L002374	Decomposing $\ti E_{\bb,\mm}=\ti E_{\b,m}+\ti E_{\bb',\mm'}$ in
L002375	$
L002376	\Om_{\mm}(E):=\bigbrac{\bb; \;
L002377	  \abs{\b^\m}<\f L2,
L002378	  \nabs{ E-\ti E_{\bb,\mm} }<\f1\ta}
L002379	$, we observe that the DOS can be written as a sum of those
L002380	in one dimension:
L002381	\begin{equation}
L002382	  \abs{ \Om_\mm(E) }
L002383	  =
L002384	  \sum_{\bb'}
L002385	  \bigabs{ \Om_m(E-\ti E_{\bb',\mm'}) }
L002386	  .
L002387	\end{equation}
L002388	Since $ab\le \f12(a^2+b^2)$, we have
L002389	\begin{align}
L002390	  &\abs{ \Om_\mm(E) }^2
L002391	  =
L002392	  \sum_{\bb',\cc'}
L002393	  \bigabs{ \Om_m(E-\ti E_{\bb',\mm'}) }
L002394	  \bigabs{ \Om_m(E-\ti E_{\cc',\mm'}) }
L002395	  \nn
L002396	  &\le
L002397	    \f12
L002398	    \sum_{\bb',\cc'}
L002399	    \bigparen{
L002400	  \bigabs{ \Om_m(E-\ti E_{\bb',\mm'}) }^2+
L002401	    \bigabs{ \Om_m(E-\ti E_{\cc',\mm'}) }^2
L002402	    }
L002403	  \nn
L002404	  &=
L002405	    {L^{d-1}}
L002406	    \sum_{\bb'}
L002407	  \bigabs{ \Om_m(E-\ti E_{\bb',\mm'}) }^2.
