L002434	\se{F. Proof of Lemma~8}
L002435	
L002436	Because the proof is essentially the same for $d=1$ and for $d \geq 2$, we
L002437	explain for $d \geq 2$.
L002438	In the proof, $K_d\spp i$ ($i=1, 2, \ldots$) denotes
L002439	a positive constant that depends only on $d$.
L002440	
L002441	
L002442	To evaluate
L002443	$\sum_{\mm\ne\zz}\abs{\ti w(\mm)}\sqrt{\II_\mm}$
L002444	in \eqref{eq-drhto-ineq} for $d \geq 2$,
L002445	we first take the sum over $\mm$ that has the same value of
L002446	$\norminf\mm=:m$.
L002447	Since there are
L002448	$2d$ possibilities for $m^\m=\pm m$,
L002449	the sum over $\mm\ne\zz$
L002450	is bounded by $2d$ times the value of
L002451	the case of $m^1=+m$.
L002452	Writing $\mm':=(m^2,...,m^d)$, and using Lemma~7 to
L002453	bound  $\II_\mm$ in terms of
L002454	$\II_m$ as $\II_\mm \leq (V^2/L^2) \, \II_m$,
L002455	we have
L002456	\begin{align}
L002457	  &
L002458	  \f1V\sum_{\mm\ne\zz}\abs{\ti w(\mm)}\sqrt{\II_\mm}
L002459	    \nn
L002460	  &\le \f{2d}L
L002461	    \sum_{1\le m<L/2}
L002462	    \abs{\ti w_1(m)}
L002463	    \sqrt{\II_m}
L002464	    \sum_{\norminf{\mm'}\le m}
L002465	    \abs{\ti w(\mm')}
L002466	    \nn
L002467	  &= \f{2d}L
L002468	    \sum_{1\le m<L/2}
L002469	    \abs{\ti w_1(m)}
L002470	    \sqrt{\II_m} \,
L002471	    \Bigparen{ \sum_{k=-m}^m \abs{\ti w_1(k)} }^{d-1}.
L002472	    \label{eq-sum-sep}
L002473	\end{align}
L002474	
L002475	Let us estimate each part of the sum.
L002476	First, using \eqref{eq-w1-bound.11}
L002477	and
L002478	splitting the sum over $m$,
L002479	we
L002480	have
L002481	\footnote{Since the summand is decreasing in $|k|$, we can use the
L002482	integral to bound the sum rigorously.  Similar remarks apply to
L002483	subsequent similar treatments.}
L002484	\begin{align}
L002485	  &\sum_{k=-m}^m
L002486	    \abs{\ti w_1(k)}
L002487	    \le
L002488	    1+2\Bigceil{\f n2}+
L002489	    2\sum_{k=\ceil{\f n2}+1}^m \f n{2k}
L002490	    \nn
L002491	    &
L002492	    \leq
L002493	    1+2\Bigceil{\f n2} + n \int_{\ceil{\f n2}}^m\f{\dd x}x
L002494	      \le n+2+n\log m.
L002495	    \label{eq-sum-w}
L002496	\end{align}
L002497	This can be further simplified
L002498	by
L002499	$m \leq L/2$  and $L>10^4$,
L002500	\begin{align}
L002501	  \sum_{k=-m}^m
L002502	  \abs{\ti w_1(k)}
L002503	  &\leq
L002504	    2 n \log L.
L002505	    \label{eq-sum-w-simple}
L002506	\end{align}
L002507	Second, because $\abs{C_m} \geq 8|m|/L$ holds from \eqref{eq-tiE},
L002508	Lemma~6 implies
L002509	\begin{align}
L002510		\II_m \leq
L002511		L^2 \, \frac{\log (\frac{8 |m| \tau}{L})}{\frac{8 |m| \tau}{L}}
L002512		+ 4L.
L002513	\end{align}
L002514	Since $\sqrt{a+b}\le\sqrt a+\sqrt b$
L002515	for $a,b\ge0$,
L002516	this implies
L002517	\begin{align}
L002518	  \sqrt{\II_m}
L002519	  	&\le
L002520	 	\frac{L \{\log (\frac{8 \tau}{L})\}^{1/2}
L002521		+ L \{\log m\}^{1/2}}{\bigl (\frac{8 m \tau}{L} \bigr )^{1/2}}
L002522	  + 2 \sqrt{L} .
L002523	    \label{eq-sqrt-IIm}
L002524	\end{align}
L002525	
L002526	We now plug
L002527	these
L002528	into \eqref{eq-sum-sep}.
L002529	From \eqref{eq-sum-w-simple},
L002530	the contribution to \eqref{eq-sum-sep} from
L002531	the second term of \eqref{eq-sqrt-IIm}
L002532	is bounded above by
L002533	\begin{align}
L002534	  \frac{2d}{L}
L002535	  (2 n \log L)^{d-1} \times 2 \sqrt{L}
L002536	    \sum_{1\le m<L/2}
L002537	    \abs{\ti w_1(m)} .
L002538		\label{eq-2sqrtL.11}
L002539	\end{align}
L002540	The sum
L002541	in \eqref{eq-2sqrtL.11}
L002542	is bounded as in
L002543	\eqref{eq-sum-w-simple},  so that
L002544	\eqref{eq-2sqrtL.11} is bounded by
L002545	\begin{align}
L002546		K^{(1)}_d (n \log L)^d/\sqrt{L} .
L002547		\label{eq-2sqrtL.13}
L002548	\end{align}
L002549	
L002550	To bound the contribution  to \eqref{eq-sum-sep} from the first term of \eqref{eq-sqrt-IIm},
L002551	we first simplify a power of the RHS of \eqref{eq-sum-w} as
L002552	$(n+2+n\log m)^{d-1}\le
L002553	K^{(2)}_d n^{d-1} \{1+(\log m)^{d-1} \}$,
L002554	and then
L002555	bound the product of $\{1+(\log m)^{d-1} \}$ and
L002556	the numerator of the first term of \eqref{eq-sqrt-IIm}
L002557	as
L002558	\begin{align}
L002559		&
L002560		\{1+(\log m)^{d-1} \}
L002561		\bigl \{ L \{\log (\tfrac{8 \tau}{L})\}^{1/2}
L002562		+ L \{\log m\}^{1/2} \bigr \} \,
L002563		\nonumber \\
L002564		&
L002565		\leq K^{(3)}_d L \{\log (\tfrac{8 \tau}{L})\}^{1/2} \, m^{1/4}
L002566		+ K^{(4)}_d L \, m^{1/4}
L002567		\nonumber \\
L002568		&
L002569		\leq
L002570		K^{(5)}_d \, L \,  \{\log (\tfrac{8 \tau}{L})\}^{1/2} \, m^{1/4}
L002571		.
L002572	\end{align}
L002573	In the above, we first expanded the product, then  bounded
L002574	various powers of $\log m$ by
L002575	$K^{(i)}_d m^{1/4}$ with appropriate choices of $K^{(i)}_d$, and
L002576	finally used the fact that  $\log(\frac{8 \tau}{L}) \geq 1$,
L002577	to combine the two terms into one.
L002578	Using also \eqref{eq-w1-bound.11}, we bound
L002579	the contribution to \eqref{eq-sum-sep}
L002580	from the first term of \eqref{eq-sqrt-IIm}   by
L002581	\begin{align}
L002582		K^{(6)}_d n^{d-1} \Bigl ( \frac{\log (\frac{8 \tau}{L})}{\frac{8 \tau}{L}}
L002583	  	\Bigr )^{1/2}
L002584		\sum_{1\le m<L/2}
L002585		\Bigl ( 1 \wedge \frac{n}{2m} \Bigr ) \frac{1}{m^{1/4}}
L002586		.
L002587		\label{eq-log-contri.11}
L002588	\end{align}
L002589	The sum over $m$ is handled as was done in \eqref{eq-sum-w},
L002590	and is bounded by $K^{(7)}_d n$.  As a result,
L002591	the contribution from the first term of \eqref{eq-sqrt-IIm}
L002592	is bounded by
L002593	\begin{equation}
L002594	  K^{(8)}_d n^{d} \Bigl ( \frac{\log (\frac{8 \tau}{L})}{\frac{8 \tau}{L}}
L002595	  \Bigr )^{1/2}
L002596	  \le
L002597	  K^{(8)}_d n^{d} \Bigl ( \frac{\log (\frac{\tau}{L})}{\frac{\tau}{L}}
L002598	  \Bigr )^{1/2} ,
L002599	  \label{eq-eq-log-contri.31}
L002600	\end{equation}
L002601	since $\log x/x$ is decreasing in $x>1$.
L002602	
L002603	Combining \eqref{eq-2sqrtL.13} and  \eqref{eq-eq-log-contri.31}
L002604	proves
L002605	Lemma~8.
L002606	\qed
